const AUTONOMY_SKIP_BINDING = { 'at-capacity': 'concurrency-cap', 'no-capability': 'no-capability', 'disabled': 'paused', 'caught-up': 'stale-fast-forward', 'already-running': 'in-flight', 'stale-lock-reclaimed': 'lease-reclaim' };
